// Segmentación inteligente por 3 verticales de Vanware:
// 1. Sin Web -> Desarrollo de Sitio Web / Landing Page de Alta Conversión
// 2. Servicios / Clínicas / Inmobiliarias -> Automatización IA WhatsApp
// 3. Empresas B2B / Mayoristas -> Sistema de Gestión y Software a Medida

const items = $input.all();
const results = [];

const IA_KEYWORDS = [
  'dentist', 'dentista', 'odontologia', 'clinic', 'clinica', 'medico', 'salud',
  'veterinarian', 'veterinaria', 'real_estate', 'inmobiliaria', 'car_dealer', 'concesionaria',
  'lawyer', 'abogado', 'consultor', 'agencia', 'turismo', 'hotel', 'hostel'
];

function capitalize(str) {
  if (!str) return '';
  return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
}

function cleanCompanyName(name) {
  if (!name) return 'su equipo';
  let clean = name.replace(/\b(S\.A\.|S\.R\.L\.|S\.A\.S\.|S\.C\.|INC\.|LLC)\b/gi, '').trim();
  if (clean === clean.toUpperCase() && clean.length > 3) {
    clean = clean.split(' ').map(w => capitalize(w)).join(' ');
  }
  return clean;
}

for (const item of items) {
  const row = item.json;
  const email = (row.Mail || row.mail || row.Email || row.email || '').trim().toLowerCase();

  if (!email || !email.includes('@') || !email.includes('.')) continue;
  if (email.endsWith('@example.com') || email.endsWith('@sentry.io')) continue;

  const nombre = cleanCompanyName(row.Nombre || row.nombre || row.Name || 'su equipo');
  const ciudad = (row.Ciudad || row.ciudad || row.Region || 'su ciudad').trim();
  const rubroRaw = (row.Rubro || row.rubro || row.Categoria || row.rubro_overture || '').toLowerCase();
  const tieneWeb = (row.Tiene_Web || row.tiene_web || row.sitio_web || '').toString().toLowerCase();

  const isSinWeb = tieneWeb === 'no' || tieneWeb === '' || tieneWeb === 'false';
  const isIA = IA_KEYWORDS.some(k => rubroRaw.includes(k));

  let producto = '';
  let introTexto = '';
  let ben1 = '';
  let ben2 = '';
  let ben3 = '';
  let resultado = '';
  let asunto = '';

  if (isSinWeb) {
    // VERTICAL 1: SITIOS WEB & LANDINGS
    producto = 'nuestro desarrollo de Sitios Web y Tiendas Online de Alta Conversión';
    introTexto = `noté que hoy no tienen un sitio web oficial activo para captar clientes que buscan servicios como los suyos en Google desde ${ciudad}.`;
    ben1 = 'Tener presencia profesional en Google y captar clientes que hoy eligen a la competencia';
    ben2 = 'Diseño ultra rápido adaptado 100% a celulares con botón directo a WhatsApp';
    ben3 = 'Estructura clara de servicios y catálogo para filtrar consultas y acelerar ventas';
    resultado = 'duplicar las consultas comerciales recibidas desde canales digitales';
    asunto = `Propuesta de Sitio Web para ${nombre}`;
  } else if (isIA) {
    // VERTICAL 2: AUTOMATIZACIÓN IA PARA WHATSAPP
    producto = 'nuestro Sistema de Automatización con IA para WhatsApp';
    introTexto = `desarrollamos asistentes con Inteligencia Artificial que atienden, filtran y agendan consultas de clientes por WhatsApp las 24 hs sin demoras.`;
    ben1 = 'Atención inmediata 24/7 sin dejar clientes esperando fuera de horario comercial';
    ben2 = 'Calificación automática de prospectos y agendamiento directo en el calendario comercial';
    ben3 = 'Sincronización de cada conversación en un CRM para seguimiento de oportunidades';
    resultado = 'reducir un 70% los tiempos de respuesta y no perder prospectos fuera de horario';
    asunto = `Consulta para ${nombre}`;
  } else {
    // VERTICAL 3: SOFTWARE & SISTEMAS DE GESTIÓN A MEDIDA
    producto = 'nuestro desarrollo de Sistemas de Gestión y Software a Medida';
    introTexto = `desarrollamos plataformas a medida para empresas que necesitan centralizar stock, clientes, pedidos y facturación en un solo sistema.`;
    ben1 = 'Control total de stock, despachos y compras en tiempo real desde una sola pantalla';
    ben2 = 'Automatizar facturación y seguimiento de pedidos sin planillas de Excel desactualizadas';
    ben3 = 'Reducir más de 12 horas semanales dedicadas a tareas administrativas repetitivas';
    resultado = 'ordenar sus operaciones de punta a punta y ganar control total del negocio';
    asunto = `Una pregunta sobre ${nombre}`;
  }

  const avatarUrl = 'https://vanware.com.ar/santiago.png';
  const bgWoodUrl = 'https://vanware.com.ar/hero-fluted-wood.png';
  const calendlyUrl = 'https://calendly.com/vanware-sys/30min';

  const htmlContent = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Vanware</title>
</head>
<body style="margin:0; padding:0; background-color:#EBE7DF; font-family:-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; -webkit-font-smoothing:antialiased; color:#222222;">

  <table width="100%" border="0" cellspacing="0" cellpadding="0" style="background-color:#EBE7DF; padding:30px 10px;">
    <tr>
      <td align="center">

        <table width="100%" border="0" cellspacing="0" cellpadding="0" style="max-width:520px; background-color:#F4F0EA; border-radius:28px; overflow:hidden; box-shadow:0 12px 35px rgba(0,0,0,0.07);">

          <!-- HERO ACANALADO MADERA ROJO/BORGOÑA -->
          <tr>
            <td style="padding:12px 12px 0 12px;">
              <table width="100%" border="0" cellspacing="0" cellpadding="0" background="${bgWoodUrl}" style="background-image:url('${bgWoodUrl}'); background-size:cover; background-position:center; background-color:#680E14; border-radius:20px; text-align:center; overflow:hidden;">

                <!-- Barra superior -->
                <tr>
                  <td style="padding:18px 20px 10px 20px;">
                    <table width="100%" border="0" cellspacing="0" cellpadding="0">
                      <tr>
                        <td align="left">
                          <span style="font-size:16px; font-weight:800; color:#FFFFFF; letter-spacing:-0.3px;">
                            &#9673; Vanware
                          </span>
                        </td>
                        <td align="right">
                          <a href="https://vanware.com.ar" style="font-size:11px; color:#F0C4C8; text-decoration:none; margin-left:12px;">Sistemas</a>
                          <a href="https://vanware.com.ar" style="font-size:11px; color:#F0C4C8; text-decoration:none; margin-left:12px;">Soluciones</a>
                          <a href="https://vanware.com.ar" style="font-size:11px; color:#F0C4C8; text-decoration:none; margin-left:12px;">Contacto</a>
                        </td>
                      </tr>
                    </table>
                  </td>
                </tr>

                <!-- Título Hero -->
                <tr>
                  <td style="padding:14px 20px 6px 20px;">
                    <h1 style="margin:0; font-size:25px; line-height:1.2; font-weight:700; color:#FFFFFF;">
                      Notamos algo<br>
                      <span style="font-family:'Georgia', serif; font-style:italic; font-weight:normal; color:#FAD5D8;">que vale la pena compartir</span>
                    </h1>
                    <p style="margin:10px auto 0 auto; font-size:13px; line-height:1.45; color:#E8B4B8; max-width:360px;">
                      Encontramos su empresa analizando operaciones en ${ciudad} y creemos que podemos optimizar su día a día.
                    </p>
                  </td>
                </tr>

                <!-- Foto de Santiago Recortada -->
                <tr>
                  <td align="center" style="padding-top:10px; line-height:0;">
                    <img src="${avatarUrl}" alt="Santiago de Vanware" width="220" style="display:block; max-width:220px; width:100%; height:auto; border:0; vertical-align:bottom; border-radius:100px 100px 0 0;">
                  </td>
                </tr>

              </table>
            </td>
          </tr>

          <!-- MENSAJE PERSONALIZADO -->
          <tr>
            <td style="padding:26px 26px 14px 26px; text-align:center;">
              <p style="margin:0 0 12px 0; font-size:17px; font-weight:700; color:#1C1A19;">
                Hola ${nombre},
              </p>
              <p style="margin:0; font-size:14px; line-height:1.6; color:#383533;">
                Mi nombre es Santiago, de <strong>Vanware</strong>. Nos dedicamos a la venta e implementación de soluciones digitales para empresas, y les escribo porque ${introTexto}
              </p>
            </td>
          </tr>

          <!-- TARJETA INTERIOR BLANCA: BENEFICIOS -->
          <tr>
            <td style="padding:4px 20px 18px 20px;">
              <table width="100%" border="0" cellspacing="0" cellpadding="0" style="background-color:#FFFFFF; border-radius:20px; padding:22px 20px; border:1px solid #E5E0D8;">

                <tr>
                  <td align="center" style="padding-bottom:12px;">
                    <span style="display:inline-block; background-color:#FDEEEE; color:#8F1820; font-size:11px; font-weight:700; letter-spacing:0.4px; text-transform:uppercase; padding:4px 12px; border-radius:20px;">
                      &bull; Propuesta a medida
                    </span>
                  </td>
                </tr>

                <tr>
                  <td align="center" style="padding-bottom:18px;">
                    <h2 style="margin:0; font-size:21px; line-height:1.25; color:#1A1817; font-weight:700;">
                      Tres mejoras clave.<br>
                      <span style="font-family:'Georgia', serif; font-style:italic; color:#8F1820; font-weight:normal;">Gran impacto operativo.</span>
                    </h2>
                    <p style="margin:6px 0 0 0; font-size:12px; color:#78726A;">
                      En concreto, ${producto} permite:
                    </p>
                  </td>
                </tr>

                <!-- Bullets -->
                <tr>
                  <td>
                    <table width="100%" border="0" cellspacing="0" cellpadding="0">
                      <tr>
                        <td width="24" valign="top" style="padding:6px 0; font-size:14px;">&#x1F7E2;</td>
                        <td valign="top" style="padding:6px 0 6px 8px; font-size:13px; line-height:1.45; color:#2E2C2A;">
                          ${ben1}
                        </td>
                      </tr>
                      <tr>
                        <td width="24" valign="top" style="padding:6px 0; font-size:14px;">&#x1F7E2;</td>
                        <td valign="top" style="padding:6px 0 6px 8px; font-size:13px; line-height:1.45; color:#2E2C2A;">
                          ${ben2}
                        </td>
                      </tr>
                      <tr>
                        <td width="24" valign="top" style="padding:6px 0; font-size:14px;">&#x1F7E2;</td>
                        <td valign="top" style="padding:6px 0 6px 8px; font-size:13px; line-height:1.45; color:#2E2C2A;">
                          ${ben3}
                        </td>
                      </tr>
                    </table>
                  </td>
                </tr>

                <!-- Resultado -->
                <tr>
                  <td style="padding-top:14px; border-top:1px dashed #E2DDD5;">
                    <p style="margin:0; font-size:12px; line-height:1.5; color:#5E5851; text-align:center;">
                      &#x1F680; Ya ayudamos a empresas a <strong>${resultado}</strong>.
                    </p>
                  </td>
                </tr>

              </table>
            </td>
          </tr>

          <!-- LLAMADO A LA ACCION (BOTON CALENDLY) -->
          <tr>
            <td style="padding:8px 24px 26px 24px; text-align:center;">
              <p style="margin:0 0 16px 0; font-size:13px; line-height:1.5; color:#47433F;">
                Si les interesa, pueden coordinar una <strong>llamada breve de 15 minutos</strong> para mostrarles cómo funciona en vivo y cotizarlo según su necesidad puntual:
              </p>

              <table border="0" cellspacing="0" cellpadding="0" align="center">
                <tr>
                  <td align="center" style="border-radius:50px; background-color:#781219;">
                    <a href="${calendlyUrl}" target="_blank" style="display:inline-block; padding:13px 30px; font-size:13px; font-weight:700; color:#FFFFFF; text-decoration:none; border-radius:50px;">
                      Coordinar una llamada &rarr;
                    </a>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

          <!-- PIE DE PAGINA -->
          <tr>
            <td style="background-color:#EBE5DC; padding:16px 20px; text-align:center; border-top:1px solid #DFDAD0;">
              <p style="margin:0 0 3px 0; font-size:12px; font-weight:600; color:#2E2B29;">
                Santiago &bull; Vanware
              </p>
              <p style="margin:0; font-size:11px; color:#78726A;">
                Venta e implementación de software empresarial &bull; <a href="https://vanware.com.ar" style="color:#78726A; text-decoration:underline;">vanware.com.ar</a>
              </p>
            </td>
          </tr>

        </table>

      </td>
    </tr>
  </table>

</body>
</html>`;

  results.push({
    json: {
      id: row.id || '',
      mail: email,
      nombre: nombre,
      ciudad: ciudad,
      rubro: rubroRaw,
      asunto: asunto,
      cuerpo_html: htmlContent
    }
  });
}

return results;
